import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router';
import api from './api';
// import api from '../api/api';

const SearchResult = () => {
  const [properties, setProperties] = useState([]);
  const [searchParams] = useSearchParams();
  console.log("searchParams")


  useEffect(() => {
    console.log('Inside fetchProperties')
    const fetchProperties = async () => {
      try {
        console.log('inside fetchProperties')
        const query = searchParams.toString();
        // const response = await fetch(`http://localhost:8080/api/properties/search?${searchParams}`, {
        //   method: 'GET',
        //   headers: {
        //     'Content-Type': 'application/json'
        //   }
        // })

        const response = await api.get(`http://localhost:8080/api/properties/search?${searchParams}`);
        console.log(response.data);
        setProperties(response.data);

        console.log(properties);

      } catch (error) {
        console.error('Error fetching properties:', error);
        setProperties( {
          _id: ObjectId('677f8ee9824e776f04132291'),
          type: 'land',
          price: 10000000,
          phone: '9039911575',
          email: 'ravisongare@outlook.com',
          description: 'propert is near highway',
          location: 'Indore',
          googleLocation: 'indore',
          images: [ 'uploads/1736412905922-homejpg.jpg' ],
          videos: [ 'uploads/1736412905935-download.jpg' ],
          __v: 0
        },
        {
          _id: ObjectId('6780c527e679a5cd47148ea9'),
          type: 'land',
          price: 10000000,
          phone: '9039911575',
          email: 'ravisongare@outlook.com',
          description: 'sadss',
          location: 'Indore',
          googleLocation: 'indore',
          images: [ 'uploads/1736492327693-homejpg.jpg' ],
          videos: [ 'uploads/1736492327705-download.jpg' ],
          __v: 0
        },
        {
          _id: ObjectId('6780cc76e679a5cd47148ec1'),
          type: 'Flate',
          price: 5000000,
          phone: '9039911575',
          email: 'ravisongare@outlook.com',
          description: 'erwer',
          location: 'mumbai',
          googleLocation: 'mumbai',
          images: [ 'uploads/1736494198451-download.jpg' ],
          videos: [ 'uploads/1736494198451-download.jpg' ],
          __v: 0
        });
      }
    };
    fetchProperties();
  }, [searchParams]);

  return (
    <div>
      <h4>{searchParams.get("location")},
        {searchParams.get("priceMin")},
        {searchParams.get("priceMax")},
        {searchParams.get("size")},
        {searchParams.get("type")},
        {searchParams.get("rentOrSell")}</h4>


      {properties.length ? (
        properties.map((property) => (
          <div key={property._id} style={{ border: '1px solid #ccc', padding: '10px', margin: '10px', borderRadius: '10px', display: 'flex', gap: '15px' }}>
            <div>
              {property.images[0]}
              <div>
                <img src={`http://localhost:8080/${property.images[0]}`} alt="This is a car image" width={200} /> {/* Use the image */}
              </div>
              <h3>{property.type} for {property.for}</h3>
              <p>Area: {property.size} Sq. ft.</p>
              <p>Price: ₹ {property.price}</p>
              <p>{property.location}</p>
              <p>{property.description}</p>
              <p>{property.price}</p>
              <p>{property.email}</p>
              <p>{property.phone}</p>
              <button style={{ backgroundColor: 'red', color: 'white', border: 'none', borderRadius: '5px', padding: '5px 10px', marginRight: '10px' }}>Contact</button>
              <button style={{ backgroundColor: 'green', color: 'white', border: 'none', borderRadius: '5px', padding: '5px 10px' }}>Whatsapp</button>
            </div>


            {/* <img src={`http://localhost:5000/${property.images[0]}`} alt={property.type} style={{ width: '100px', height: '100px' }} /> */}
          </div>

        ))
      ) : (
        <p>No properties found</p>
      )}
    </div>
  );
};

export default SearchResult;
